#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>

#include "k5-int.h"
#include "krb5.h"

#define kMinInputLength 20
#define kMaxInputLength 100

extern int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{//src/tests/misc/test_chpw_message.c

    if (Size < kMinInputLength || Size > kMaxInputLength){
        return 0;
    }

    char *msg;
    krb5_data DataInput;
    krb5_context context;

    krb5_init_context(&context);

    DataInput = make_data((void *)Data, Size);

    krb5_chpw_message(context, &DataInput, &msg);

    free(msg);
    krb5_free_context(context);
    return 0;
}

476:krb5_chpw_message(krb5_context context, const krb5_data *server_string,
---
krb5_chpw_message(krb5_context context, const krb5_data *server_string,
                  char **message_out)
{
    krb5_error_code ret;
    krb5_data *string;
    char *msg;

    *message_out = NULL;

    /* If server_string contains an AD password policy, construct a message
     * based on that. */
    ret = decode_ad_policy_info(server_string, &msg);
    if (ret == 0 && msg != NULL) {
        *message_out = msg;
        return 0;
    }

    /* If server_string contains a valid UTF-8 string, return that. */
    if (server_string->length > 0 &&
        memchr(server_string->data, 0, server_string->length) == NULL &&
        krb5int_utf8_normalize(server_string, &string,
                               KRB5_UTF8_APPROX) == 0) {
        *message_out = string->data; /* already null terminated */
        free(string);
        return 0;
    }

    /* server_string appears invalid, so try to be helpful. */
    msg = strdup(_("Try a more complex password, or contact your "
                   "administrator."));
    if (msg == NULL)
        return ENOMEM;

    *message_out = msg;
    return 0;
}
